  const hot=D.hot.slice(0,5).map(h=>`<div class="row"><span>${P(dk,h[6])}</span><span class="m">${h[5]} pts · ${esc(short(h[1]))}</span></div>`).join('');
  const top=D.rows.slice(0,5).map(r=>`<div class="row"><span>${r[10]}. ${P(dk,D.rows.indexOf(r))}</span><span class="m">${r[6]} pts</span></div>`).join('');
